#!/usr/bin/env python3
"""Generate bounded insertion templates from supported commands and language references."""
from pathlib import Path
import json,argparse
from help_command_metadata import command_metadata
root=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();rows=[]
for name,c in command_metadata().items():
 if c['parseable']:rows.append((0,name,name+' '))
lua={'print':'print("")','calc.eval':'calc.eval("2+3")','screen.clear':'screen.clear("black")','screen.pixel':'screen.pixel(10,10,"white")','screen.line':'screen.line(10,10,100,100,"white")','screen.rect':'screen.rect(10,10,40,30,"white",false)','screen.circle':'screen.circle(80,80,20,"white",false)','screen.text':'screen.text(10,10,"Hello","white")','screen.font':'screen.font("compact")','screen.measure':'screen.measure("Hello")','screen.show':'screen.show()','screen.sprite':'screen.sprite("DEMO.sprite",10,10)','plot.clear':'plot.clear()','plot.window':'plot.window(-4,4,-2,2)','plot.function2d':'plot.function2d(function(x) return math.sin(x) end)','plot.surface':'plot.surface(function(x,y) return x*y end)','plot.show':'plot.show()','keyboard.poll':'keyboard.poll()','keyboard.wait':'keyboard.wait(1000)','keyboard.down':'keyboard.down("left")','system.sleep':'system.sleep(100)','system.millis':'system.millis()','sound.beep':'sound.beep(880,100)','sound.stop':'sound.stop()'}
rows += [(2,n,t) for n,t in lua.items()]
chip={'CLS':'CLS','RET':'RET','EXIT':'EXIT','LOW':'LOW','HIGH':'HIGH','SCR':'SCR','SCL':'SCL','JP':'JP start','CALL':'CALL routine','JPOFF':'JPOFF 0x200','SCD':'SCD 2','SKP':'SKP V0','SKNP':'SKNP V0','SHR':'SHR V0','SHL':'SHL V0','SAVE':'SAVE V0','LOAD':'LOAD V0','FLAGSAVE':'FLAGSAVE V0','FLAGLOAD':'FLAGLOAD V0','LD':'LD V0, 0','ADD':'ADD V0, 1','RND':'RND V0, 0x0F','SE':'SE V0, 0','SNE':'SNE V0, 0','OR':'OR V0, V1','AND':'AND V0, V1','XOR':'XOR V0, V1','SUB':'SUB V0, V1','SUBN':'SUBN V0, V1','DRW':'DRW V0, V1, 5','DB':'DB 0xF0, 0x90, 0xF0','DW':'DW 0x6000'}
rows += [(1,n,t+'\n') for n,t in chip.items()];rows.sort(key=lambda r:(r[0],r[1].casefold()));assert all(0<len(r[2].encode())<=256 for r in rows)
def location(lang,text):
 if '(' in text:
  start=text.index('(')+1
  if text[start:start+1]=='"':
   start+=1;end=text.find('"',start)
  elif text[start:start+8]=='function':
   start=text.find('return ',start)+7;end=text.find(' end',start)
  else:
   end=min([n for n in [text.find(',',start),text.find(')',start)] if n>=0],default=start)
 elif lang==1 and ' ' in text:
  start=text.index(' ')+1;end=text.find(',',start)
  if end<0:end=len(text.rstrip())
 else:start=end=len(text)
 return len(text[:start].encode()),len(text[start:max(start,end)].encode())
text='// Generated by tools/generate_editor_commands.py. GPL-3.0.\n#pragma once\nnamespace pico_editor_commands {\nstruct Command {unsigned language;const char *name,*text;unsigned cursor,selection;};\ninline constexpr Command entries[]={\n'+''.join('{'+str(lang)+','+json.dumps(n)+','+json.dumps(t)+','+','.join(map(str,location(lang,t)))+'},\n' for lang,n,t in rows)+'};\n}\n'
path=root/'pico/ui/editor_commands.h'
if a.check:assert path.read_text()==text
else:path.write_text(text)
print('PASS:',len(rows),'bounded command insertion templates')
